  var BASE_STATE = IMP + "\n\nvoid main() {\n  runApp(const MaterialApp(home: Pantalla()));\n}\n" + STATEFUL('Pantalla') + "\n\nclass _PantallaState extends State<Pantalla> {\n  // tu código aquí (estado)" + STATE_BODY;
  var BASE_DART = "// tu código aquí (funciones)\n\nvoid main() {\n  // tu código aquí (main)\n}";
  var BASE_DART_ASYNC = "import 'dart:async';\n\n// tu código aquí (funciones)\n\nFuture<void> main() async {\n  // tu código aquí (main)\n}";
